import { __test } from './worker.js';
import { writeFileSync } from 'node:fs';
const { ROLE_ARCHETYPE_LABELS, ROLE_FAMILIES, ACTIVITIES, BUSINESS_LINES, LEADERSHIP_LEVELS, RISK_FLAGS } = __test;
const lines = [
  '# JEV Taxonomy v4.1', '',
  '> Generated from worker.js. Do not edit this file by hand.', '',
  '## Card contract', '',
  'The card exposes exactly five dimensions: **Role Archetype**, **Primary Activity**, **Business Line**, **Leadership Level**, and **Role Risk**. Internal signals (`postingType`, title signals, nouls, evidence and usage) are not additional card dimensions.', '',
  '## Role Archetype', '', '| Code | Label | Family |', '|---|---|---|'
];
for (const [code, label] of Object.entries(ROLE_ARCHETYPE_LABELS)) {
  const family = code.match(/^(CS|IR|RC|OP|PS|TE|CF)/)?.[1] || '';
  lines.push(`| \`${code}\` | ${label} | ${ROLE_FAMILIES[family] || ''} |`);
}
lines.push('', '## Primary Activity', '', '| Code | Definition |', '|---|---|---|');
for (const [code, definition] of Object.entries(ACTIVITIES)) lines.push(`| \`${code}\` | ${definition} |`);
lines.push('', '## Business Line', '', '| Code | Definition |', '|---|---|---|');
for (const [code, definition] of Object.entries(BUSINESS_LINES)) lines.push(`| \`${code}\` | ${definition} |`);
lines.push('', '## Leadership Level', '', '| Code | Definition |', '|---|---|---|');
for (const [code, definition] of Object.entries(LEADERSHIP_LEVELS)) lines.push(`| \`${code}\` | ${definition} |`);
lines.push('', '## Role Risk', '', '| Code | Label | Severity ceiling |', '|---|---|---|');
for (const [code, definition] of Object.entries(RISK_FLAGS)) lines.push(`| \`${code}\` | ${definition.label} | ${definition.severity} |`);
lines.push('', '## Deterministic safeguards', '', '- A non-job posting neutralises every dimension.', '- Insufficient evidence never becomes a confident profession guess.', '- Primary Activity is a model judgement; archetype defaults are only a low-confidence fallback.', '- Leadership is gated by explicit people/team evidence; title alone is not management evidence.', '- Five independent structural risks are bounded and each emitted flag includes a reader-verifiable reason.', '- The browser receives no provider secret; all provider calls use the same-origin Worker proxy.');
writeFileSync('jev-taxonomy-v4.1.md', lines.join('\n') + '\n');
